import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const DATA = [{ id: "1", name: "Чихэвч" }, { id: "2", name: "Гар цаг" }, { id: "3", name: "Цүнх" }];

// энд бичнэ үү: Row-г React.memo-оор боо
function Row({ name }) {
  return <Text testID="row" style={styles.row}>{name}</Text>;
}

function App() {
  return (
    <FlatList
      style={styles.s}
      data={DATA}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => <Row name={item.name} />}
    />
  );
}

const styles = StyleSheet.create({ s: { flex: 1, padding: 16 }, row: { padding: 14, backgroundColor: "#f1f5f9", borderRadius: 10, marginBottom: 8 } });

registerRootComponent(App);

